import pandas as pd

dates = pd.to_datetime(["2024-02-10", "2025-01-31", "2025-12-05"])
for d in dates:
    start = d.to_period("M").to_timestamp()
    end = d + pd.offsets.MonthEnd(0)
    print(start.date(), end.date())

